"""Build the preliminary teacher/timing study from exported, reviewed evidence."""
from html import escape
import hashlib
import json
from pathlib import Path
import re
from build_site import ASSET_COUNTS, e, link, p, section, small, table
from site_navigation import project_tabs,experiment_subtabs
from prethinking_trace_content import load_traces,example_table,thinking_figure,appendix,timeline_data
from prethinking_completion_content import load_completion,completion_results,completion_appendix,completion_timeline

ROOT=Path(__file__).resolve().parents[1]

def eq(tex):return '<div class="equation" tabindex="0" role="region" aria-label="Equation; scroll horizontally if needed">\\['+escape(tex)+'\\]</div>'

def main():
    d=json.loads((ROOT/'research/prethinking-pilot/study.json').read_text());s=d['data'];t=d['teacher'];a=d['allocation'];traces=load_traces();completed=load_completion();ASSET_COUNTS.update(Table=0,Figure=0)
    opening=p('This preliminary study asks two practical questions: what useful work can a quiet assistant prepare from an ongoing group conversation, and how much of it can fit before another transcript update arrives? It uses a real 37-minute workshop-planning meeting and a local text teacher. The model generates private chain of thought (CoT), meaning reasoning text that is not spoken to participants. This phase does not train an audio student, run the interaction layer S1, or demonstrate a live duplex assistant.')
    opening+='<div class="callout"><h3>The first timing finding</h3>'+p('At an assumed 10 output tokens/s and 0.5 s of model setup per update, sentence-by-sentence delivery leaves a median of 17 output tokens; 19.7% of distinct arrival intervals leave none. Batching increases the available budget by delaying new context. That tradeoff needs to be measured, rather than treating every new sentence as a reason to cancel all prior thinking.')+'</div>'
    opening+=p('The selected first goal is tracking constraints, conflicts and unresolved questions for participant C. Tool calls are proposed, never executed. Table 2 now pairs real transcripts with verbatim thinking excerpts; the appendix includes all 64 complete captured thinking outputs and their exact prompts. The broader restaurant/travel catalog is separate brainstorming. Useful facts, conditional deductions and unanswered questions are distinct from fluent private reasoning.')

    if completed:opening+=p('The latest follow-up generates the single-round example to natural completion, measures warmed inference speed, and compares two-round teacher continuation conditions. Its completed-run appendix preserves ten new full prompts and outputs; the earlier 64 capped traces remain available separately. Completion and causal input checks are assessed separately from grounding quality.')

    corpus=p('AMI EN2003a contains three linguistics students planning a postgraduate workshop. The official documentation distinguishes this real meeting from the fictitious office-move exercises that also appear in its non-scenario category. The released manual transcript supplies speaker labels and word timestamps; no VAD, ASR or diarization model was needed for this phase. Word timing is an annotation resource, not proof of an online recognizer’s accuracy.')+link('Official non-scenario meeting descriptions','https://groups.inf.ed.ac.uk/ami/corpus/nonscenariomeetings.shtml')
    corpus+=table('pilot-corpus-table',0,'Recording and annotation inventory; counts were extracted from the downloaded release.', ['Item','Value','Meaning'],[
        [e('Meeting / audio duration'),e('EN2003a / 2240.277 s (37.34 min)'),e('Original mono headset mix, 16 kHz PCM; metadata duration is 2240.341 s.')],
        [e('Active speakers / lexical words'),e('A: 4322; B: 1152; C: 868'),e('Three active participants; punctuation excluded. The D annotation is empty.')],
        [e('Chunks / distinct arrivals'),e('650 / 640'),e('Per-speaker sentence endings or a 15 s cap; simultaneous arrivals are combined.')],
        [e('Arrival gap'),e('Raw-chunk median 2.08 s; distinct-arrival median 2.25 s'),e('Chunks become available after their last word, plus an assumed 0.5 s transcript delay.')],
        [e('Selected party'),e('C'),e('A perspective for useful preparation; C remains a human participant, not a fabricated assistant role.')]
    ],searchable=False)
    corpus+=p('We retain all already-available speech, including C’s past utterances. We do not supply C’s future response, meeting summaries, future plans or an offline persona as context. Selecting a party does not by itself define an assistant’s duties: here the teacher is instructed to help C follow the discussion without speaking. This choice should be revisited if the goal becomes participant replacement or an explicitly addressed assistant.')
    corpus+=p('The text inputs use compact speaker-labeled lines, with stable evidence IDs. Exact word times, chunk boundaries and availability remain in the records. Full JSON metadata for each past utterance pushed a late prefix to 27,310 tokens; compact input passed a real-tokenizer check with a worst tested 11,118 tokens plus 1024 output tokens within the 16,384-token context. This was fixed before GPU inference. Compactness has a limitation: delivery order is not always speech-onset order during overlap; the next prompt revision should make overlap timing more explicit.')

    ideas=p('Table 2 contains actual EN2003a transcript passages and verbatim passages from the generated Qwen private thinking. Grounded excerpts and failures are labeled separately. Each example links to its complete thinking and full executed prompt in the appendix. A useful selected passage does not make the rest of its trace reliable.')
    ideas+=example_table(d,traces)
    ideas+=p('A model inference should not be attributed as something a participant said. “A volunteered to draft the call” can cite A’s utterance. “The timetable may not allow enough preparation time” is the model’s deduction, with its supporting speakers and assumptions. A tool result needs a separate source and retrieval time; it does not become true merely because a speaker asserted it.')
    ideas+='<details><summary>Broader brainstorming catalog: categories not all represented in this recording</summary>'+p('Table 3 preserves the broader design catalog. Its examples are authored; restaurant lookup, travel and disclosure cases have not been substituted for actual teacher results.')+table('pilot-brainstorming',0,'Authored brainstorming catalog, separate from the real transcript/thinking pairs in Table 2.', ['Category / authored example','Potential preparation','Attribution and tools'],[
        [e(c['name'])+small(c['example']),e(c['preparation'])+small('Update: '+c['change']),e(c['speaker_attribution'])+small('Tools: '+c['tool_policy'])] for c in d['categories']
    ])+'</details>'
    ideas+=p('For a restaurant example, hearing a name alone rarely justifies a lookup. A useful candidate would first resolve the venue and branch, identify an active need such as a vegetarian menu or a booking deadline, and select an authoritative source. A result can persist across unrelated speech, but a changed venue, date or constraint can invalidate it. This phase deliberately records candidates without adding tool latency, sensitive queries or external-source quality as confounds.')

    causal=p(r'Let \(a_i\) be the time transcript update \(i\) is delivered, \(T_{\leq a_i}\) the attributed transcript available then, \(H_i\) retained private analysis, and \(z_i\) the teacher’s new private reasoning. The selected participant and preparation goal are part of context \(c\). The teacher’s task is:')
    causal+=eq(r'z_i\sim p_T(z\mid T_{\leq a_i},H_i,c).')
    causal+=p('This is a quiet preparation task with no unknown future question supplied. Each call receives observed transcript and, in the history condition, the actual private prefixes generated earlier. It is a fresh text generation with earlier analysis supplied explicitly as context. It is not a claim that the engine accepts new input midway through a live generation or resumes an old KV cache after changing the prompt.')
    causal+=p(r'Write \(\tilde z_i\) for the material actually generated within the current budget. The history update keeps that material, never the unseen tail of a longer completion:')
    causal+=eq(r'H_{i+1}=\operatorname{retain}(H_i,\tilde z_i).')
    causal+=p('The initial experiment retains up to eight earlier private entries, labeled completed or interrupted. Reset controls see the same transcript but no generated history. A later chunk may require correcting or ignoring prior analysis; mere continuation is not automatically the right behavior. We should judge both evidence attribution and whether old assumptions are revised.')
    causal+=p('A tempting shortcut would generate a long thought once, truncate it in a timeline, and then carry its complete content into the next call. That would leak work the simulated slow model had not performed. The rate-specific replay instead limits each real call before updating the next input. Offline future timestamps determine the counterfactual budget, but future transcript content never enters the prompt. This is still an oracle-timing experiment, not a learned online scheduling policy.')
    causal+=p('CPU checks verify word cutoffs, complete-prefix availability, overlap ordering and rejection of future reasoning. The manual-transcript release is last-word end plus 0.5 s, an illustrative fixed delay. Real streaming ASR can emit provisional words, revise them or have variable latency; a later noisy-input experiment must model those differences separately.')

    timing=p(r'Let \(r\) be an assumed output rate in tokens/s and \(h_i\) setup time for update \(i\), covering input processing before decoding. The available output-token budget before the next delivered update is:')
    timing+=eq(r'B_i=\left\lfloor r\max\left(0,a_{i+1}-a_i-h_i\right)\right\rfloor.')
    timing+=p('The formula is a timing sensitivity model. It does not say a 17-token thought is useful, that setup is constant on real hardware, or that all new context requires cancellation. Transcript release delay and model setup are separate quantities; both default to 0.5 s here. Periodic batching delays newly completed chunks until the next batch boundary. More budget therefore comes with later awareness of corrections.')
    rows=[x for x in s['simulation'] if x['rate']==10 and x['overhead']==.5]
    timing+=table('pilot-budget-table',0,'Counterfactual 10 tokens/s with 0.5 s setup; rates and setup are assumptions, not measured model speed.', ['Delivery policy','Updates','Median interval','Median tokens','Zero budget / under 32 tokens'],[
        [e(x['policy'].replace('_',' ')),str(x['updates']),f"{x['median_gap']:.2f} s",str(x['median_tokens']),f"{100*x['zero_fraction']:.1f}% / {100*x['under_32_fraction']:.1f}%"] for x in rows
    ],searchable=False)
    timing+='''<figure class="pilot-figure" id="pilot-timeline"><h3>Explore the real transcript clock</h3><div class="pilot-controls"><label>Assumed output rate<select id="pilot-rate"><option value="10">10 tokens/s</option><option value="30">30 tokens/s</option><option value="60">60 tokens/s</option><option value="100">100 tokens/s</option></select></label><label>Model setup<select id="pilot-overhead"><option value="0">0 s</option><option value="0.5" selected>0.5 s</option><option value="1">1 s</option><option value="3">3 s</option></select></label><label>Delivery policy<select id="pilot-policy"><option value="0">Each sentence/cap</option><option value="2">Batch every 2 s</option><option value="5">Batch every 5 s</option><option value="10">Batch every 10 s</option></select></label><label>View<select id="pilot-window"><option value="590,670">Participation counts</option><option value="75,175">Commitments</option><option value="1785,1860">Deadline correction</option><option value="0,2240.277">Whole meeting</option></select></label></div><p id="pilot-stat" aria-live="polite"></p><div class="pilot-plot-scroll" tabindex="0" role="region" aria-label="Transcript and potential decoding windows"><svg id="pilot-svg" viewBox="0 0 1100 240" role="img" aria-labelledby="pilot-svg-title"><title id="pilot-svg-title">Real speaker chunks and assumed token budgets</title></svg></div><label for="pilot-chunk">Inspect a transcript chunk</label><select id="pilot-chunk"></select><div class="callout" id="pilot-selection" aria-live="polite"></div><figcaption>Figure 1. Three lanes show original speaker audio spans; the bottom lane shows potential decoding time after setup and before the next delivered update. Click a chunk or select it to inspect its actual transcript. Budgets change with assumed rate, setup and batching. These bands are available capacity, not measured teacher activity or a useful-reasoning score. Only 10/60 tokens/s with 10 s batching were used in the rate-specific teacher replay.</figcaption></figure>'''
    timing+=p('For interruptions, compare three policies next: replace private work on every update; keep it unless relevant assumptions change; and finish a bounded reasoning unit while accumulating input. The first is simple but may waste useful work; the last can expose the system to stale assumptions. A task ID and evidence dependencies should decide whether a late result is accepted. Read-only retrieval may proceed independently if its query remains valid; a changing thought direction does not automatically invalidate a tool result.')
    timing+=p('Figure 2 answers a narrower timing question: given one fixed prompt and one captured token sequence, how much of that same output fits at each rate? It changes only emission time and truncation. The independently generated rate-specific replays described above have different prompts/history after interruption; those original calls remain in the appendix. The visualization does not feed a hidden tail into a subsequent call.')
    timing+=thinking_figure()

    audio=p('The clips below are original human audio, cropped from the downloaded headset mix. They let us inspect disfluencies, brief acknowledgments and corrections that clean written examples omit. Their transcripts are manual annotations; this is not a comparison against an ASR system. All audio remains aligned to the original meeting clock.')
    for n,clip in enumerate(d['clips'],3):
        audio+='<figure class="pilot-audio"><h3>'+e(clip['label'])+'</h3><audio controls preload="metadata" data-source-start="'+str(clip['start'])+'" src="../'+e(clip['path'])+'"></audio><figcaption>Figure '+str(n)+'. Original AMI EN2003a excerpt, '+str(clip['start'])+'–'+str(clip['end'])+' s. Human recording, no generated speech. CC BY 4.0; selected mono crop encoded losslessly as FLAC.</figcaption></figure>'
    audio+=link('Audio attribution and adaptation details','../assets/prethinking-pilot/ATTRIBUTION.md')

    results=p('The local teacher is Qwen3-30B-A3B-Thinking-2507, pinned to revision '+t.get('revision','144afc2f379b542fdd4e85a1fcd5e1f79112d95d')+'. It is a 30.5B-parameter mixture-of-experts model; all weights remain resident even though fewer parameters are activated per token. Its official card describes a longer native thinking mode, making this a useful test of whether a reasoning model is suitable for short preparation windows.')+link('Official model card','https://huggingface.co/Qwen/Qwen3-30B-A3B-Thinking-2507')
    results+=p('The run first compares broad and selective prompts at four real transcript prefixes, each with a 1024-token cap. It then compares reset versus retained private history across a short consecutive window of participation-count discussion, at assumed rates 10 and 60 tokens/s, 10 s batches, and seeds 17/29. Calls are executed sequentially, not paced to wall-clock speech. Generation wall time includes prefill; it is not a measured output-only token rate.')
    if a.get('teacher_total_output_tokens'):
        results+=p('All '+str(len(t['calls']))+' calls were token-cap limited, with no final-channel structured notes. They generated '+str(a['teacher_total_output_tokens'])+' tokens over '+f"{a['teacher_generation_wall_seconds']:.3f}"+' s of summed generation wall time, or '+f"{a['teacher_end_to_end_generation_tokens_per_second']:.2f}"+' tokens/s including prefill. Some private content is relevant; the missing final notes do not prove private reasoning is useless. The 10/60-token/s replay rates remain counterfactual assumptions, not measurements of this GPU’s decode rate.')
    results+='<div class="callout"><h3>Execution and content review</h3>'+p('Teacher job '+t['job_id']+': '+t['status'].replace('_',' ')+'. Recorded calls: '+str(len(t.get('calls',[])))+'. Content review: '+d['review']['status'].replace('_',' ')+'. Completion, output length and syntactically valid JSON are not usefulness or speaker-attribution passes.')+'</div>'
    if d['review'].get('findings'):
        for f in d['review']['findings']:results+='<h3>'+e(f['title'])+'</h3>'+p(f['text'])
    results+='<details><summary>Exact call inventory: prompts, budgets and generation costs</summary>'+table('pilot-calls-table',0,'Actual teacher generations. Assumed rates control token caps; wall seconds are measured offline call time.', ['Call / stage','Prompt / history','Prefix / budget','Generated / finish','Wall time'],[
        [str(c['index'])+small(c['stage']),e(c['variant']+' / '+c['history_mode'])+small('seed '+str(c['seed'])),f"{c['at']:.2f} s / {c['budget']} tokens",str(c['output_tokens'])+small(c['finish_reason']),f"{c['wall_seconds']:.3f} s"] for c in t.get('calls',[])
    ],searchable=False)+'</details>'
    results+='<details><summary>The two preparation instructions and history format</summary>'+p(d['prompts']['common'])+'<h3>Broad instruction</h3>'+p(d['prompts']['variants']['broad'])+'<h3>Selective instruction</h3>'+p(d['prompts']['variants']['selective'])+p(d['prompts']['history_semantics'])+'</details>'
    results+=table('pilot-allocation-table',0,'Allocation accounting and scope; maximum one experiment GPU active at once.', ['Job / work','GPUs / role','Dependencies and cost'],[
        [e('1071746 assets'),e('0 GPUs; audio, annotations and 61.07 GB teacher weights.'),e('Completed in 475 s; 5 allocated CPUs. No model inference.')],
        [e('1071777 superseded H100 request'),e('0 GPUs allocated; pending request cancelled.'),e('Cancelled before execution; 0 GPU-hours; no overlapping run.')],
        [e('1071792 teacher'),e('1 A100-SXM4 80 GB; only teacher on GPU 0. No shared model components.'),e('After assets/CPU checks. '+(f"{a['teacher_elapsed_seconds']} s / {a['teacher_gpu_hours']:.5f} GPU-hours." if 'teacher_elapsed_seconds' in a else 'Accounting is pending completion.'))],
        [e('Data audit / visualization'),e('0 GPUs.'),e('CPU parsing, export and browser checks; no audio-student training.')]
    ],searchable=False)
    results+=p('The initial H100 queue forecast was overnight; a one-A100 forecast was earlier, so the unallocated H100 was cancelled. GPU 1071792 started earlier than the conservative A100 estimate. The role map and actual GPU type are recorded, and no automatic two-GPU fallback is enabled. Sampled teacher peak: '+(f"{d['sampled_teacher_peak_mib']/1024:.2f} GiB." if d.get('sampled_teacher_peak_mib') else 'not yet recorded.'))

    new_results=completion_results(completed,d)
    new_appendix=completion_appendix(completed,d)

    discussion=p('The immediate design question is how to allocate scarce private reasoning to useful evidence. This recording offers commitments, uncertain quantities, alternate formats and explicit deadline revision. It also contains brief acknowledgments and unclear procedural speech that should not automatically launch a long analysis. The current model should be judged on grounding, attribution, useful deductions and revision—not how many reasoning tokens it produces.')
    discussion+=p('After inspecting the first run, a useful next comparison is a short, explicitly labeled private update versus native long CoT, with the same observed context and budget. Another is overlap-aware transcript input: compact start/end markers or a small list of overlapping utterances can prevent delivery order from being mistaken for conversational order. Keep memory maintenance as a control, and measure whether private history preserves facts or carries forward unsupported assumptions.')
    discussion+=p('The observed stale-update sequence makes serialization a priority. The current prompt lists transcript first and retained private history last; old analysis still describes its former chunks as “new.” Test the same inputs with history first and the actual new evidence plus context version last, then compare concise state against raw CoT. Do not change both and attribute recovery to ordering alone. Generated history must stay subordinate to current source evidence.')
    discussion+=p('A further input distinction matters before distillation: this first replay exposes completed chunks. During overlapping speech, audio may already contain words from another speaker’s unfinished sentence that have not been released as a chunk. An audio-student dataset should align the teacher’s available-word buffer to the actual audio cutoff across all speakers, while choosing preparation triggers separately. Sentence boundaries can schedule work without withholding every unfinished sentence from its context.')
    discussion+=p('The teacher’s own generated history is a valid input for this preliminary conditional experiment, but it changes the supervision problem. Gold teacher history may be cleaner than the later audio student’s history; student-generated prefixes and recognition uncertainty need separate evaluation. Source-transcript speaker labels are an oracle aid here. This run does not prove that an audio-conditioned student can recover the same attribution.')
    discussion+=p('This public corpus could also be familiar to a pretrained teacher. Input records verify that no future transcript or generated tail was supplied, but they cannot rule out corpus knowledge in model weights. Later causal claims need disjoint scenarios, counterfactual changes and newly recorded or independently generated held-out material.')
    discussion+=p('The brainstorming catalog is broader than the chosen first goal. External lookup can be added after entity resolution, relevance and update behavior work. It should have explicit time and cost limits, dated evidence, and a rule for invalidation. Preparatory reasoning never authorizes messaging, booking or changing the world. We can discard deep pre-thinking if cheap state updates deliver the same benefit.')
    sources=p('Data: AMI manual annotations v1.6.2 and EN2003a headset mix, current CC BY 4.0 release. Original audio was cropped and encoded losslessly; no speech was synthesized. Model: official Qwen checkpoint and tokenizer. At the user’s explicit request, this report now publishes the complete external Qwen private-channel traces and prompts. Original local files remain unchanged. The appendix audits captured Qwen output; sharing raw CoT with S1 remains a separate design decision.')
    sources+='<p>'+link('AMI download and license','https://groups.inf.ed.ac.uk/ami/download/')+' · '+link('Natural meeting descriptions','https://groups.inf.ed.ac.uk/ami/corpus/nonscenariomeetings.shtml')+' · '+link('Qwen model card','https://huggingface.co/Qwen/Qwen3-30B-A3B-Thinking-2507')+' · '+link('Study bundle','../research/prethinking-pilot/study.json')+' · '+link('High-level proposal','../prethinking.html')+'</p>'
    sections=[('pilot-question','What are we trying to learn?',opening),('pilot-corpus','The real conversation and its causal transcript',corpus),('pilot-ideas','Actual transcript and thinking examples',ideas),('pilot-causality','Conditioning on new text and prior private work',causal),('pilot-timing','How much reasoning fits between updates?',timing),('pilot-audio','Listen to the source conversation',audio),('pilot-results','Initial token-limited teacher probe (archived)',results),('pilot-discussion','What should we change or test next?',discussion),('pilot-sources','Sources and evidence boundaries',sources),('pilot-appendix','Appendix: every prompt and full captured private thinking',appendix(d,traces))]
    if completed:
        sections.insert(next(i for i,item in enumerate(sections) if item[0]=='pilot-discussion'),('pilot-completion','Single-round completion and two-round teacher samples',new_results))
        sections.insert(next(i for i,item in enumerate(sections) if item[0]=='pilot-appendix'),('completion-appendix','Appendix: completed-run prompts and private thinking',new_appendix))
    timeline=timeline_data(traces)
    if completed:
        timeline['calls']+=completion_timeline(completed)
        timeline['default_plot_index']=completed['default_plot_index']
    hero='<header class="hero"><p class="eyebrow">Experiments · Preliminary pre-thinking study</p><h1>Preparing while a group talks.</h1><p class="lede">Real workshop conversation, speaker-attributed teacher prompts and a causal timing model before audio-student training.</p><p class="meta">12 October 2026 · AMI EN2003a · 37.3 min / 3 speakers · Teacher: 1 A100 80 GB · Data and visualization: 0 GPUs</p></header>'
    nav='<nav class="jump-links" aria-label="Pilot sections">'+''.join(link(title,'#'+ident) for ident,title in [('pilot-corpus','Conversation'),('pilot-ideas','Real examples'),('pilot-causality','Causal model'),('pilot-timing','Capacity explorer'),('thinking-timeline','Transcript/token timeline'),('pilot-completion','Completion / measured speed') if completed else ('pilot-results','Teacher outputs'),('pilot-discussion','Discussion'),('completion-appendix','Completed-run appendix') if completed else ('pilot-appendix','Full prompt/CoT appendix')])+'</nav>'
    body='\n'.join(['<a class="skip-link" href="#main">Skip to study</a>','<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header>','<main id="main"><div class="container">',experiment_subtabs('prethinking'),hero,nav]+[section(i,title,b) for i,title,b in sections]+['<footer class="site-footer"><p>'+link('All experiments','index.html')+' · '+link('Pre-thinking proposal','../prethinking.html')+'</p></footer>','</div></main>'])
    cfg=r"window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},svg:{fontCache:'global'},options:{enableMenu:false}};"
    html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="Real transcript/thinking examples, complete Qwen prompt and private-output appendix, and time-aligned token-rate views."><title>Pre-thinking Pilot · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/prethinking.css"><link rel="stylesheet" href="../assets/prethinking-pilot.css"><script>'+cfg+'</script><script id="MathJax-script" defer src="../assets/vendor/mathjax/tex-svg.js"></script><script defer src="../assets/site.js"></script><script defer src="../assets/prethinking-pilot.js"></script><script defer src="../assets/prethinking-traces.js"></script></head><body>\n'+body+'\n<script id="pilot-data" type="application/json">'+json.dumps(d,ensure_ascii=False).replace('<','\\u003c')+'</script><script id="teacher-trace-data" type="application/json">'+json.dumps(timeline,ensure_ascii=False).replace('<','\\u003c')+'</script></body></html>\n'
    for asset in ['assets/prethinking-pilot.css','assets/prethinking-pilot.js','assets/prethinking-traces.js']:
        digest=hashlib.sha256((ROOT/asset).read_bytes()).hexdigest()[:12]
        html=html.replace('"../'+asset+'"','"../'+asset+'?v='+digest+'"')
    (ROOT/'experiments/prethinking-pilot.html').write_text(html)
    # Keep shared navigation current without regenerating historical experiment content.
    for path in (ROOT/'experiments').glob('*.html'):
        if path.name=='prethinking-pilot.html':continue
        original=path.read_text()
        def update(m):
            nav=m[0]
            if 'href="prethinking-pilot.html"' in nav:return nav
            return nav.replace('</nav>','<a href="prethinking-pilot.html">Pre-thinking pilot</a></nav>')
        changed=re.sub(r'<nav[^>]*aria-label="Experiment sub-tabs"[^>]*>.*?</nav>',update,original,flags=re.S)
        if changed!=original:path.write_text(changed)
    print('Built preliminary study, categories, real audio and timing explorer.')

if __name__=='__main__':main()
